import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"杂卦传","description":"周易集注 - 杂卦传","frontmatter":{"title":"杂卦传","description":"周易集注 - 杂卦传"},"headers":[],"relativePath":"zh/classics/jizhu/073.md","filePath":"zh/classics/jizhu/073.md"}'),r={name:"zh/classics/jizhu/073.md"};function i(c,p,_,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="杂卦传" tabindex="-1">杂卦传 <a class="header-anchor" href="#杂卦传" aria-label="Permalink to “杂卦传”">​</a></h1><p>杂卦者，杂乱文王之序卦也。孔子将序卦一连者，特借其一端之理以序之，其寔恐后学颠倒文王所序之卦也。一端之理在所缓也，又恐后学以序卦为定理，不知其中有错有综，有此二体，故杂乱其卦。前者居于后，后者居于前，止将二体两卦有错有综者下释其意，故乾刚坤柔，比乐师忧是也。使非有此杂卦，象必失其传矣。</p><p>乾刚坤柔。</p><p>此以错言，言乾坤之情性也。文王序卦六十四卦止乾坤坎离大过颐小过中孚八卦相错，盖伏羲圆图，乾坤坎离四正之卦本相错，四隅之卦，兑错艮，震错巽，故大过，颐，小过，中孚所以相错也。</p><p>比乐师忧。</p><p>此以综言，因二卦同体，文王相综为一卦，后言综者仿此。顺在内故乐，险在内故忧。凡综卦有四正综，四正者，比乐师忧，大有众同人亲之类也。四隅之卦，艮与震综，皆一阳二阴之卦。艮可以言震，震可以言艮，兑与巽综，皆二阳一阴之卦。兑可以言巽，巽可以言兑，如随蛊咸恒之类是也。有以正综隅，隅综正者，临观屯蒙之类是也。前儒不知乎此，所以言象失其传，而不知象即藏于错综之中，因不细玩杂卦故也。</p><p>临观之义，或与或求。</p><p>此以综言。君子之临小人也，有发政施仁之意，故与;下民之观君上也，有仰止观光之心，故求。曰或者，二卦皆可言与求也。盖求则必与，与则必求。</p><p>屯见而不失其居，蒙杂而著。</p><p>此以综言。见者居九五之位也，居者以阳居阳也。八卦正位，坎在五，言九五杂于二阴之间，然居九五之位，刚健中正，故见而不失其居。蒙九二亦杂于二阴之间，然为发蒙之主。故杂而著见，皆以坎之上下言，言蒙之坎上而为屯矣。见而不失其居，屯之坎下而为蒙矣，杂而又著。</p><p>震起也，艮止也。</p><p>此以综言，震阳起于下，艮阳止于上。</p><p>损益盛衰之始也。</p><p>此以综言，损上卦之艮，下而为益下卦之震。帝出乎震，故为盛之始。益上卦之巽，下而为损下卦之兑，说言乎兑，故为衰之始。震东兑西，春生秋杀，故为盛衰之始。</p><p>大畜时也，无妄灾也。</p><p>此以综言。大畜上卦之艮，下而为无妄下卦之震，故孔子曰刚自外来而为主于内。无妄下卦之震，上而为大畜之艮，故孔子曰刚上而尚贤。止其不能止者，非理之常，乃适然之时。得其不当得者，非理之常，乃偶然之祸。</p><p>萃聚而升不来也。</p><p>此以综言。升上卦之三阴，下而为萃之下卦。三阴同聚，故曰萃。萃下卦之三阴，上而为升之上卦，三阴齐升，故曰升。惟升故不降下而来。</p><p>谦轻而豫怠也。</p><p>此以综言。谦之上六，即豫之初六，故二爻皆言鸣。谦心虚，故自轻;豫志满，故自怠。</p><p>噬嗑食也，贲无色也。</p><p>此以综言。贲下卦之离，上而为噬嗑之上卦，故孔子曰柔得中而上行。噬嗑上卦之离，下而为贲之下卦，故孔子曰柔来而文刚。颐中有物，食其所有，白贲无色，文其所无。</p><p>兑见而巽伏也。</p><p>此以综言，与震艮同，震艮以阳起止于上下，此则以阴见伏于上下。</p><p>随无故也，蛊则饬也。</p><p>此以综言，随则以蛊上卦艮之刚，下而为震，故孔子曰刚来而下柔。蛊则以随上卦兑之柔，下而为巽，故孔子曰刚上而柔下。随无大故，故能相随，蛊有大故，故当整饬。</p><p>剥烂也，复反也。</p><p>此以综言，剥则生意渐尽而归于无，复则生意复萌而反于有。</p><p>晋昼也，明夷诛也。</p><p>此以综言。明夷下卦之离，进而为晋之上卦，故孔子曰柔进而上行，明在上而明著，明在下而明伤。</p><p>井通而困相遇也。</p><p>困上卦之兑，下而为井下卦之巽。井下卦之巽，上而为困上卦之兑。养而不穷，通也，即不困。刚过其揜，遇也，即不通。</p><p>咸速也，恒久也。</p><p>此以综言。故孔子曰柔上而刚下，刚上而柔下。有感则速，速则婚姻及时。有恒则久，久则夫妇偕老。</p><p>涣离也，节止也。</p><p>此以综言。节上卦坎之刚来居涣之下卦，涣上卦巽之柔来居节之下卦。风散水故涣，涣则离而不止。泽防水故节，节则止而不离。</p><p>解缓也，蹇难也。</p><p>此以综言。蹇下卦之艮往而为解上卦之震，出险之外，安舒宽缓之时，居险之下，大难切身之际。</p><p>睽外也，家人内也。</p><p>此以综言。睽下卦之兑，即家人上卦之巽。睽于外而不相亲，亲于内而不相睽。</p><p>否泰反其类也。</p><p>此以综言。大往小来，小往大来，故反其类。</p><p>大壮则止，遁则退也。止当作上</p><p>此以综言，止字乃上字之误。二卦相综，遁之三爻即大壮之四爻，上字指大壮之四爻而言，退字指遁之三爻而言，皆相比于阴之爻也。孔子因周公三爻四爻之辞，故发此上退二字，言大壮则壮于大舆之輹，上往而进，遁则退而畜止臣妾，使制于阳，不使之浸而长也。故大壮则上，遁则退。</p><p>大有众也，同人亲也。</p><p>此以综言。同人下卦之离进居大有之上卦，大有上卦之离来居同人之下卦，势统于一，所爱者众，情通于同，所与者亲。</p><p>革去故也，鼎取新也。</p><p>此以综言。鼎下卦之巽进而为革上卦之兑，水火相息，有去故之义。水火相烹，有从新之理。</p><p>小过过也，中孚信也。</p><p>此以错言，过者逾其常，信者存其诚。</p><p>丰多故，亲寡旅也。</p><p>此以综言。旅下卦之艮，即丰上卦之震。人处丰盛，故多故旧。人在穷途，故寡亲识。</p><p>离上而坎下也。</p><p>此以错言，炎上润下。</p><p>小畜寡也，履不处也。</p><p>此以综言，二卦皆以柔为主。小畜柔得位但寡不能胜，众阳所以不能畜，故曰寡也。履柔不得位，惟以悦体履虎尾，故曰不处也。不处者非所居也，故六三小象曰位不当。</p><p>需不进也，讼不亲也。</p><p>此以综言，天水相上下，安分待时，故不进。越理求胜，故不亲。</p><p>大过颠也，颐养正也。（依蔡氏改正）</p><p>此以错言。弱其本末故颠，择其大小故正。《序卦》曰：颐者养也，不养则不可动，故受之以大过。有此作证，蔡氏方改正，所以《序卦》有功于易。</p><p>既济定也，未济男之穷也。（依蔡氏改正）</p><p>此以综言，水火相为上下，六位皆当故定，三阳失位故穷。</p><p>归妹女之终也，渐女归待男行也。（依蔡氏改正）</p><p>此以综言。归妹下卦之兑，进而为渐上卦之巽，渐下卦之艮进而为归妹上卦之震，归妹者女事之终，待男者女嫁之礼。</p><p>姤遇也，柔遇刚也。夬决也，刚决柔也，君子道长，小人道消也。（依蔡氏改正）</p><p>此以综言。君子小人，迭为盛衰，犹阴阳迭相消长。一柔在五阳之下，曰柔遇刚者，小人之遭遇，君子之所忧也。一柔在五阳之上，曰刚决柔者，君子之道长，小人之所忧也。易之为书，吉凶消长，进退存亡，不过此理此数而已，故以是终之。</p>',66)])])}const m=a(r,[["render",i]]);export{h as __pageData,m as default};
